import type { Locale } from '@/i18n/routing';

type Guide = readonly [name: string, history: string, highlights: string, visit: string, photoTip: string];
export type Area = 'kupittaa' | 'old-town' | 'centre' | 'river';
type Operator = 'city' | 'sports' | 'museum' | 'parishes' | 'fari' | 'avan' | 'sibelius' | 'etthem' | 'art' | 'forum' | 'unknown';
type Photo = { url: string; source: string; credit: string; license: string; licenseUrl: string };

type Place = {
  slug: string;
  area: Area;
  mapName: string;
  operator: Operator;
  source: string;
  text: Record<Locale, Guide>;
  photo?: Photo;
};

const parks = 'https://www.turku.fi/en/outdoor-recreation-and-hiking/parks';
const museumGuide = 'https://en.visitturku.fi/museums-turku';

function place(
  slug: string, area: Area, mapName: string, operator: Operator, source: string,
  en: Guide, fi: Guide, sv: Guide, zh: Guide, photo?: Photo,
): Place {
  return { slug, area, mapName, operator, source, text: { en, fi, sv, zh }, photo };
}

