export const areas = ['kupittaa', 'old-town', 'centre', 'river'] as const;

export function nearbyMap(name: string) {
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(name)}`;
}

export function walkingMap(origin: string, destination: string) {
  return `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(destination)}&travelmode=walking`;
}

export function relatedPlaces(place: Place) {
  const group = places.filter((candidate) => candidate.area === place.area);
  const index = group.findIndex((candidate) => candidate.slug === place.slug);
  return [group[(index + 1) % group.length], group[(index + group.length - 1) % group.length]];
}

